// 0 <= key, value <= 109

class TimeLimitedCache {
  kvs = new Map<number, [value: number, expireMs: number]>();

  constructor() {
  }

  set(key: number, value: number, duration: number): boolean {
    const oldValue = this.get(key);
    const expireMs = Date.now() + duration;
    this.kvs.set(key, [value, expireMs]);
    return oldValue !== -1;
  }

  get(key: number): number {
    if (!this.kvs.has(key)) {
      return -1;
    }
    const [value, expireMs] = this.kvs.get(key);
    if (expireMs <= Date.now()) {
      this.kvs.delete(key);
      return -1;
    }
    return value;
  }

  count(): number {
    const entries = Array.from(this.kvs.entries());
    let n = 0;
    for (const [key, [_value, expireMs]] of entries) {
      if (expireMs <= Date.now()) {
        this.kvs.delete(key);
        continue;
      }

      n++;
    }
    return n;
  }
}

