type MultiDimensionalArray = (number | MultiDimensionalArray)[];

// OOM
function flat2(arr: MultiDimensionalArray, n: number): MultiDimensionalArray {
  if (n <= 0) {
    return arr;
  }
  const arr2 = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      arr2.push(...item);
    } else {
      arr2.push(item);
    }
  }
  return flat2(arr2, n - 1);
};

function flat(arr: MultiDimensionalArray, n: number): MultiDimensionalArray {
  if (n <= 0) {
    return arr;
  }
  const arr2 = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      const flattedItem = flat(item, n - 1);
      arr2.push(...flattedItem);
    } else {
      arr2.push(item);
    }
  }
  return arr2;
};

